package com.example.crm.auth;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service public class JwtService {final SecretKey key; final long ttl; public JwtService(@Value("${app.jwt.secret:change-this-development-secret-key-at-least-32-chars}") String secret,@Value("${app.jwt.access-ttl-seconds:900}") long ttl){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;} public String create(UserAccount u){return Jwts.builder().subject(u.getUsername()).claim("role",u.getRole().name()).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(ttl))).signWith(key).compact();} public String username(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{username(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} public long ttl(){return ttl;} }
